import {products,chapterFor} from './content.js?v=learning-life-1';
import {productStories} from './product-journey.js?v=learning-life-1';
const eyebrow=s=>`<p class="eyebrow"><span class="eyebrow-line"></span>${s}</p>`;
export function growthHTML(kind){return kind==='growth'?senseHTML():`${eyebrow('05 / CONNECTED INTELLIGENCE')}<h1 class="chinese-heading">能力齊了，<br>讓它們<em>一起行動。</em></h1><div class="story-copy"><h2>神經連起訊息，肢體把決定帶回現場。</h2><p>從感知、學習，到記憶、思考與技能。<br>每塊產品找到自己的位置，彼此連結成完整智慧。</p></div><div class="growth-mappings"><div><b>感官</b><span>相機、感測器與 WinEdge</span></div><div><b>學習</b><span>AIWinOps × NumOps</span></div><div><b>思考</b><span>WinChat · RAG + Agent + Skill</span></div><div><b>肢體</b><span>現場設備與工作流程</span></div></div><p class="growth-question">但同一個世界，<br>為什麼影像與數據還要分開？</p><button class="primary-button" data-next-chapter>One more thing ✦</button>`}
export function senseHTML(mode='overview'){
 if(mode==='cameras')return `${eyebrow('01 / VISION BECOMES HARDWARE')}<h1 class="chinese-heading">從眼睛，<br>到現場的<em>視覺。</em></h1><div class="story-copy"><h2>同樣是看見，不同現場有不同的眼睛。</h2></div><div class="sense-channels camera-channels"><div><span>01</span><section><h3><button class="camera-reference" data-case="camera-basler">Basler 工業相機 <span>官方產品圖 ↗</span></button></h3><p>搭配鏡頭、光源與取像時機，觀察產線細節。</p></section></div><div><span>02</span><section><h3>IP Camera</h3><p>透過網路串流，將場域畫面帶進系統。</p></section></div><div><span>03</span><section><h3>USB Camera</h3><p>連接近端設備，取得工作站與近距離畫面。</p></section></div></div><p class="sense-bridge">不同取像方式，匯入影像 Pipeline。<br>Edge 硬體搭載 WinEdge-V，在現場判讀影像。</p><div class="sense-actions"><button class="text-button" data-sense="back">回到感知全貌 ↶</button><button class="primary-button" data-sense="next">再認識現場的數字 ↗</button></div>`;
 if(mode==='data')return `${eyebrow('01 / DATA BECOMES UNDERSTANDING')}<h1 class="chinese-heading">不只看見，<br>還要讀懂<em>數字。</em></h1><div class="story-copy"><h2>設備的變化，也有自己的語言。</h2></div><div class="sense-channels data-channels"><div><span>01</span><section><h3>Modbus</h3><p>連接儀表與感測器，接收溫度、壓力等量測值。</p></section></div><div><span>02</span><section><h3>MC Protocol</h3><p>讀取 PLC 與設備訊號，理解運轉狀態。</p></section></div><div><span>03</span><section><h3>Database</h3><p>帶入資料庫與歷史紀錄，連起每次變化的脈絡。</p></section></div></div><p class="sense-bridge">Edge 硬體搭載 WinEdge-N，<br>把現場數據轉成可判讀、可追蹤的資訊。<br><span class="sense-learning-bridge">有了影像與數據，接著在真實專案中學習。</span></p><div class="sense-actions"><button class="text-button" data-sense="back">回看影像感知 ↶</button><button class="primary-button" data-sense="next">開始學習與累積 ↗</button></div>`;
 return `${eyebrow('01 / FIRST CONTACT')}<h1 class="chinese-heading">智慧的初生，<br>從<em>感知世界</em>開始。</h1><div class="story-copy"><h2>像初生的生命，逐步打開感官。</h2></div><div class="sense-channels"><div><span>01</span><section><h3>看見細節</h3><p>鏡頭・光源・相機・取像與影像串流</p></section></div><div><span>02</span><section><h3>感受變化</h3><p>溫度・震動・壓力・感測器與 PLC</p></section></div><div><span>03</span><section><h3>連起脈絡</h3><p>設備狀態・資料庫・通訊與時間資訊</p></section></div></div><p class="sense-bridge">WinEdge-V / N 接住輸入，<br>串起前處理、AI 推論與現場回饋。</p><button class="primary-button" data-sense="next">讓眼睛接上現場 ↗</button>`;
}
export function journeyUI(state){
 const p=products.find(p=>p.id===state.id),n=productStories[state.id],t=n.topics[state.selected];
 if(state.phase==='overview')return {story:`${eyebrow(p.verb)}<h1 class="chinese-heading">${n.title}</h1><div class="story-copy"><h2>${n.bridge}</h2><p>從三個現場問題，累積一塊新的能力。</p></div><div class="journey-topics">${n.topics.map((t,i)=>`<button data-journey="select" data-topic="${i}"><span>0${i+1}</span><strong>${t.title}</strong><b>↗</b></button>`).join('')}</div><button class="primary-button" data-journey="next">走進第一塊經驗 ↗</button>`,detail:'<div class="journey-caption">EVERY CAPABILITY STARTS WITH A REAL NEED.</div>'};
 if(state.phase==='selecting'||state.phase==='focus')return {story:`${eyebrow(`0${state.selected+1} / ${t.tag}`)}<h1 class="journey-heading">${t.title}</h1><div class="story-copy"><h2>${t.question}</h2><p>${t.copy}</p></div><ol class="journey-points">${t.points.map((v,i)=>`<li><span>0${i+1}</span>${v}</li>`).join('')}</ol><div class="journey-actions"><button class="text-button" data-journey="back">上一段 ↶</button><button class="primary-button" data-journey="next" ${state.phase==='selecting'?'disabled':''}>${state.selected===2&&state.canFuse?'融合成 '+p.name:'下一塊經驗'} ↗</button></div>`,detail:t.image?`<div class="journey-evidence"><img src="./assets/${t.image}" alt="${t.source}"><small>${t.source}</small></div>`:`<div class="skill-flow">${t.flow.map((v,i)=>`<span><small>0${i+1}</small>${v}</span>`).join('<b>→</b>')}</div>`};
 if(state.phase==='fusing')return {story:'',detail:`<div class="journey-birth"><p>EXPERIENCE BECOMES A BUILDING BLOCK</p><h1>把一次次的需要，<br><em>組成可以再用的能力。</em></h1></div>`};
 return {born:true};
}
